<?php
require_once __DIR__.'/../config/auth.php';$user=require_role(['kasir','owner']);$pageTitle='Kas Harian';$uid=(int)$user['id'];$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=(string)($_POST['action']??'');try{if($action==='open'){$check=$pdo->prepare('SELECT id FROM cash_sessions WHERE user_id=? AND ditutup_pada IS NULL LIMIT 1');$check->execute([$uid]);if($check->fetchColumn())throw new RuntimeException('sesi kas masih terbuka. tutup dulu sebelum membuka sesi baru.');$opening=max(0,(float)($_POST['modal_awal']??0));$st=$pdo->prepare('INSERT INTO cash_sessions (user_id,modal_awal) VALUES (?,?)');$st->execute([$uid,$opening]);log_activity('open_cash','Modal awal '.money($opening));$message='kasir berhasil dibuka.';}elseif($action==='close'){$sessionId=(int)($_POST['session_id']??0);$actual=max(0,(float)($_POST['kas_akhir']??0));$note=clean_text((string)($_POST['catatan']??''),500);$st=$pdo->prepare('SELECT * FROM cash_sessions WHERE id=? AND user_id=? AND ditutup_pada IS NULL');$st->execute([$sessionId,$uid]);$session=$st->fetch();if(!$session)throw new RuntimeException('sesi kas tidak aktif atau bukan milikmu.');$up=$pdo->prepare('UPDATE cash_sessions SET kas_akhir=?,catatan=?,ditutup_pada=NOW() WHERE id=?');$up->execute([$actual,$note,$sessionId]);log_activity('close_cash','Kas akhir aktual '.money($actual));$message='kasir berhasil ditutup.';}}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'operasi kas gagal. coba lagi.';}}
$st=$pdo->prepare('SELECT * FROM cash_sessions WHERE user_id=? AND ditutup_pada IS NULL ORDER BY dibuka_pada DESC LIMIT 1');$st->execute([$uid]);$active=$st->fetch();$historySt=$pdo->prepare('SELECT * FROM cash_sessions WHERE user_id=? ORDER BY dibuka_pada DESC LIMIT 10');$historySt->execute([$uid]);$history=$historySt->fetchAll();$sales=0;$cashCount=0;if($active){$st=$pdo->prepare("SELECT COALESCE(SUM(total),0) total,COUNT(*) n FROM orders WHERE kasir_id=? AND created_at>=? AND status_bayar='Lunas' AND metode_bayar='Kasir' AND status_pesanan<>'Dibatalkan'");$st->execute([$uid,$active['dibuka_pada']]);$s=$st->fetch();$sales=(float)$s['total'];$cashCount=(int)$s['n'];}$expected=$active?(float)$active['modal_awal']+$sales:0;
require __DIR__.'/../includes/admin-header.php'; ?>
<?php if($message):?><div class="flash flash-ok"><?= h($message) ?></div><?php endif;?><?php if($error):?><div class="flash flash-error"><?= h($error) ?></div><?php endif;?><div class="grid xl:grid-cols-[1fr_1fr] gap-5 items-start"><section class="card p-5 sm:p-7"><p class="section-kicker">operasional harian</p><h2 class="font-serif text-2xl mt-2">status kasir</h2><?php if(!$active):?><p class="text-sm text-coffee/60 mt-2">belum ada sesi kasir terbuka. isi modal awal untuk memulai shift.</p><form method="post" class="space-y-4 mt-5"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="open"><div><label class="field-label">Modal awal kas (Rp)</label><input class="field" type="number" name="modal_awal" min="0" step="1000" value="0" required></div><button class="btn btn-coffee">Buka kasir</button></form><?php else:?><span class="status-pill status-green mt-3">Sesi sedang berjalan</span><div class="grid grid-cols-2 gap-3 mt-5"><div class="rounded-2xl bg-white p-4"><p class="text-xs text-coffee/55">Modal awal</p><b class="text-xl block mt-2"><?= money($active['modal_awal']) ?></b></div><div class="rounded-2xl bg-white p-4"><p class="text-xs text-coffee/55">Penjualan tunai lunas</p><b class="text-xl block mt-2"><?= money($sales) ?></b><small class="text-xs text-coffee/50"><?= $cashCount ?> transaksi</small></div><div class="rounded-2xl bg-white p-4 col-span-2"><p class="text-xs text-coffee/55">Perkiraan uang kas</p><b class="font-serif text-3xl block mt-2"><?= money($expected) ?></b></div></div><form method="post" class="space-y-4 mt-6"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="close"><input type="hidden" name="session_id" value="<?= (int)$active['id'] ?>"><div><label class="field-label">Uang kas aktual saat tutup (Rp)</label><input class="field" type="number" min="0" step="1000" name="kas_akhir" required></div><div><label class="field-label">Catatan shift (opsional)</label><textarea class="field" name="catatan" rows="2"></textarea></div><button class="btn btn-caramel" data-confirm="Yakin ingin menutup sesi kasir?">Tutup kasir</button></form><?php endif;?></section><section class="card p-5"><h2 class="font-serif text-2xl">Riwayat sesi kas</h2><div class="table-wrap mt-4"><table class="admin-table"><thead><tr><th>Buka</th><th>Modal</th><th>Kas akhir</th><th>Status</th></tr></thead><tbody><?php foreach($history as $s):?><tr><td><?= h(date('d/m H:i',strtotime($s['dibuka_pada']))) ?><?php if($s['ditutup_pada']):?><span class="block text-xs text-coffee/50">tutup <?= h(date('d/m H:i',strtotime($s['ditutup_pada']))) ?></span><?php endif;?></td><td><?= money($s['modal_awal']) ?></td><td><?= $s['kas_akhir']!==null?money($s['kas_akhir']):'—' ?></td><td><span class="status-pill <?= $s['ditutup_pada']?'status-green':'status-orange' ?>"><?= $s['ditutup_pada']?'Tutup':'Terbuka' ?></span></td></tr><?php endforeach;?><?php if(!$history):?><tr><td colspan="4">belum ada riwayat kas.</td></tr><?php endif;?></tbody></table></div><p class="text-xs text-coffee/50 mt-4">perkiraan kas menghitung modal awal + transaksi berstatus lunas dengan metode “Bayar di kasir”. QRIS di luar hitungan uang tunai.</p></section></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
